p_chkl_c:		; call chkl (normal)
			pop hl			; got
			ld de, var_chkl_got
			ld bc, 4
			ldir
			pop hl			; want
			ld de, var_chkl_want
			ld bc, 4
			ldir
			ld (p_chkl_rs), sp
			ld sp, p_chkl
			jp ntc_xn
p_chkl_r:		; end of chkl
			ld sp, (p_chkl_rs)
			jp ntc_xn
p_chk_c:		; call chk (normal)
			pop hl			; got
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_got), de
			pop hl			; want
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_want), de
			ld (p_chk_rs), sp
			ld sp, p_chk
			jp ntc_xn
p_chk_r:		; end of chk
			ld sp, (p_chk_rs)
			jp ntc_xn
p_chks_c:		; call chks (normal)
			pop hl			; got
			ld de, var_chks_got
			ld b, 40
p_chks_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si0_e
			inc hl
			inc de
			djnz p_chks_si0
			xor a
			ld (de), a
p_chks_si0_e:
			pop hl			; want
			ld de, var_chks_want
			ld b, 40
p_chks_si1:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si1_e
			inc hl
			inc de
			djnz p_chks_si1
			xor a
			ld (de), a
p_chks_si1_e:
			ld (p_chks_rs), sp
			ld sp, p_chks
			jp ntc_xn
p_chks_r:		; end of chks
			ld sp, (p_chks_rs)
			jp ntc_xn
p_twice_c:		; call twice (normal)
			pop hl			; v
			ld de, var_twice_v
			ld bc, 4
			ldir
			ld hl, 0
			ld (var_twice_twice), hl
			ld (var_twice_twice+2), hl
			ld (p_twice_rs), sp
			ld sp, p_twice
			jp ntc_xn
p_twice_r:		; end of twice
			ld sp, (p_twice_rs)
			jp ntc_xn
p_addto_c:		; call addto (normal)
			pop hl			; x
			ld (p_addto_a0), hl
			ld de, var_addto_x
			ld bc, 4
			ldir
			pop hl			; y
			ld de, var_addto_y
			ld bc, 4
			ldir
			ld (p_addto_rs), sp
			ld sp, p_addto
			jp ntc_xn
p_addto_r:		; end of addto
			ld de, (p_addto_a0)
			ld hl, var_addto_x
			ld bc, 4
			ldir
			ld sp, (p_addto_rs)
			jp ntc_xn
p_fact_c:		; call fact (normal)
			pop hl			; k
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_fact_k), de
			ld hl, 0
			ld (var_fact_fact), hl
			ld (var_fact_fact+2), hl
			ld hl, 0
			ld (var_fact_r), hl
			ld (var_fact_r+2), hl
			ld (p_fact_rs), sp
			ld sp, p_fact
			jp ntc_xn
p_fact_r:		; end of fact
			ld sp, (p_fact_rs)
			jp ntc_xn

